def zero_on_finish(self, info):
    """Stop must not cancel the zero/off command itself."""
    self.changed.emit('Обнуление тока и выключение выхода…')
    try:
        info['magnet_final'] = self.magnet.call('zero', timeout=90)
        info['magnet_finish_action'] = 'zeroed'
        return ''
    except Exception as exc:
        info['magnet_finish_action'] = 'zero_failed'
        self.log.emit('Не удалось подтвердить обнуление магнита: ' + str(exc))
        return str(exc)

